                   CASE WHEN [i].[NodeTypeId] IS DISTINCT FROM [d].[NodeTypeId] THEN N'NodeTypeId' END,
                   CASE WHEN CAST([i].[Title] AS VARBINARY (MAX)) IS DISTINCT FROM CAST([d].[Title] AS VARBINARY (MAX)) THEN N'Title' END,
                   CASE WHEN [i].[SortOrder] IS DISTINCT FROM [d].[SortOrder] THEN N'SortOrder' END,
