                   CASE WHEN [i].[CreatedByUserId] IS DISTINCT FROM [d].[CreatedByUserId] THEN N'CreatedByUserId' END,
                   CASE WHEN [i].[ModifiedAt] IS DISTINCT FROM [d].[ModifiedAt] THEN N'ModifiedAt' END,
