           OR [i].[SortOrder] IS DISTINCT FROM [d].[SortOrder]
           OR [i].[CreatedAt] IS DISTINCT FROM [d].[CreatedAt]
           OR [i].[CreatedByUserId] IS DISTINCT FROM [d].[CreatedByUserId]
           OR [i].[ModifiedAt] IS DISTINCT FROM [d].[ModifiedAt]
